theorem pair_lang_fin_subseq {as : Stream' A} {ss : Stream' M.State} {m n : ℕ}
    (h_next : ∀ k, ss (k + 1) ∈ M.next (ss k) (as k)) (h_m_n : m ≤ n) :
    as.extract m n ∈ M.PairLang (ss m) (ss n)

theorem pair_path_split {s s' : M.State} {al0 al1 : List A} {ss : Stream' M.State}
    (h : M.PairPath s s' (al0 ++ al1) ss) :
    M.PairPath s (ss al0.length) al0 ss ∧ M.PairPath (ss al0.length) s' al1 (ss.drop al0.length)

theorem pair_path_concat {s s' t: M.State} {al0 al1 : List A} {ss0 ss1 : Stream' M.State}
    (h0 : M.PairPath s t al0 ss0) (h1 : M.PairPath t s' al1 ss1) :
    M.PairPath s s' (al0 ++ al1) (fun k ↦ if k < al0.length + 1 then ss0 k else ss1 (k - al0.length))

theorem pair_acc_lang_frequently_from_run {as : Stream' A} {ss : Stream' M.State} {φ : Stream' ℕ}
    (h_next : ∀ k, ss (k + 1) ∈ M.next (ss k) (as k)) (h_acc : ∃ᶠ k in Filter.atTop, ss k ∈ acc) (h_mono : StrictMono φ) :
    ∃ᶠ m in Filter.atTop, as.extract (φ m) (φ (m + 1)) ∈ M.PairAccLang acc (ss (φ m)) (ss (φ (m + 1)))

theorem na_FinRun_of_FinRun' [Inhabited A] {n : ℕ} {as : Fin n → A} {ss : Fin (n + 1) → M.State}
    (h : M.FinRun' n as ss) : M.FinRun n (fun k ↦ if h : k < n then as ⟨k, h⟩ else default)
      (fun k ↦ if h : k < n + 1 then ss ⟨k, h⟩ else ss 0)

theorem na_loop_fin_run_exists {n : ℕ} {as : Stream' A} {ss' : Stream' M.State}
    (h_run' : M.FinRun n as ss') (h_acc' : ss' n ∈ acc) :
    ∃ ss, (M.Loop acc).FinRun n as ss ∧ ss n = inl () ∧ (∀ k < n, k > 0 → ss k = inr (ss' k))

theorem acc_lang_loop_concat :
    ((M.Loop acc).AcceptedLang {inl ()}) * ((M.Loop acc).AcceptedLang {inl ()}) ⊆
    (M.Loop acc).AcceptedLang {inl ()}

private lemma na_oi2_lemma2 {as : Stream' A} {ss : Stream' (NA.OI2 M acc).State}
    (h_run : (NA.OI2 M acc).InfRun as ss)
    (h_inf0 : ∃ᶠ k in atTop, ss k ∈ { s | s.1 0 ∈ acc 0 })
    (h_inf1 : ∃ᶠ k in atTop, ss k ∈ { s | s.1 1 ∈ acc 1 }) :
      ∃ᶠ k in atTop, ss k ∈ { s | s.1 0 ∈ acc 0 ∧ s.2 = 0 } ∪ { s | s.1 1 ∈ acc 1 ∧ s.2 = 1 }

theorem na_hist_fin_run_exists {n : ℕ} {as : Stream' A} {ss : Stream' M.State}
    (h_init : hist_init.Nonempty) (h_next : ∀ s a, (hist_next s a).Nonempty)
    (h : M.FinRun n as ss) : ∃ hs : Stream' H, (M.addHist hist_init hist_next).FinRun n as (fun k ↦ (ss k, hs k))

theorem na_hist_inf_run_exists {as : Stream' A} {ss : Stream' M.State}
    (h_init : hist_init.Nonempty) (h_next : ∀ s a, (hist_next s a).Nonempty)
    (h : M.InfRun as ss) : ∃ hs : Stream' H, (M.addHist hist_init hist_next).InfRun as (fun k ↦ (ss k, hs k))

theorem ConcatInf_mono {L0 L0' : Set (List A)} {L1 L1' : Set (Stream' A)}
    (h0 : L0 ⊆ L0') (h1 : L1 ⊆ L1') :
    L0 * L1 ⊆ L0' * L1'

theorem mem_ConcatInf_IterOmega {L0 L1 : Set (List A)} {as : Stream' A}
    (h : as ∈ L0 * L1^ω) : ∃ φ : Stream' ℕ, StrictMono φ ∧
      as.extract 0 (φ 0) ∈ L0 ∧ ∀ m, as.extract (φ m) (φ (m + 1)) ∈ L1

lemma ramsey_lemma {C : Type} {cs : Set C} {φ : ℕ → ℕ} {col : ℕ → ℕ → C}
    (h_fin : cs.Finite) (h_mono : StrictMono φ) (h_col : ∀ i j, i < j → col (φ i) (φ j) ∈ cs) :
    ∃ c ∈ cs, ∃ σ : ℕ → ℕ, StrictMono σ ∧ ∀ i j, i < j → col (φ (σ i)) (φ (σ j)) = c

theorem extract_eq_extract {xs xs' : Stream' X} {m n m' n' : ℕ}
    (h : xs.extract m n = xs'.extract m' n') :
    n - m = n' - m' ∧ ∀ k < n - m, xs (m + k) = xs' (m' + k)

theorem congruence_ample_saturates_union {L : Set (Stream' A)}
    (h_amp : c.Ample) (h_sat : c.Saturates L) :
    L =  ⋃ s, ⋃ t, if (c.ConcatOmegaLang s t ∩ L).Nonempty then c.ConcatOmegaLang s t else ∅
